Q: How to write a CAML Query so that the result contains Column1 and Column2? A: <p>Try with the code below:</p>

<pre><code>    XmlDocument xmlDoc = new System.Xml.XmlDocument();
    XmlElement query = xmlDoc.CreateElement("Query");
    XmlElement viewFields = xmlDoc.CreateElement("ViewFields");
    XmlElement queryOptions = xmlDoc.CreateElement("QueryOptions");

    query.InnerText = "&lt;Where&gt;&lt;Gt&gt;&lt;FieldRef Name='ID'/&gt;&lt;Value Type='Number'&gt;0&lt;/Value&gt;&lt;/Gt&gt;&lt;/Where&gt;";
    viewFields.InnerXml = "&lt;FieldRef Name=\"Column1\" /&gt;&lt;FieldRef Name=\"Column2\" /&gt;";
    queryOptions.InnerXml = "";

    try
    {
        XmlNode ndListItems = listService.GetListItems("List_Name", null, query, viewFields, null, queryOptions, null);
    }
</code></pre>

<p>For references: <a href="https://msdn.microsoft.com/en-us/library/lists.lists.getlistitems(v=office.12).aspx#Anchor_2" rel="nofollow">msdn example</a></p>
